Q: what is the different between Single List and List Node? A: <p>ListNode is a node in the linked list and there is some code to better understand the ListNode.</p>

<pre><code>public class List
 {
     // return a linked list based on parameters list and soFar
     public static ListNode process(ListNode list, ListNode soFar)
     {
         if (list == null) {
             return soFar;
         }
         else {
             ListNode temp = list.getNext();
             list.setNext(soFar);
             return process(temp,list);
         }
      }

      // return a new linked list based on parameter n

      public static ListNode create(int n)
      {
        ListNode list = null;
        for(int k=1; k &lt;= n; k++) {
            list = new ListNode(new String(""+k), list);
        }
        return list;
      }

      // print a linked list

      public static void print(ListNode list)
      {
        while (list != null) {
            System.out.print(list.getValue()+" ");
            list = list.getNext();
        }
        System.out.println();
      }
 }
</code></pre>
